// دمج ألعاب GameDistribution في خريطة التصنيفات بعد القائمة المنسّقة يدويًا
const gamesByCategoryMap: Record<CategorySlug, readonly string[]> = (
  Object.keys(gamesByCategoryStatic) as CategorySlug[]
).reduce(
  (acc, cat) => ({
    ...acc,
    [cat]: [
      ...gamesByCategoryStatic[cat],
      ...gdGames.filter((g) => g.categorySlug === cat).map((g) => g.slug),
    ],
  }),
  {} as Record<CategorySlug, readonly string[]>,
);

const slugToGame: Map<string, Game> = new Map(allGames.map((g) => [g.slug, g]));

function toExcludeSet(excludeSlugs?: Iterable<string>): Set<string> | null {
  if (!excludeSlugs) return null;
  const s = excludeSlugs instanceof Set ? excludeSlugs : new Set(excludeSlugs);
  return s.size === 0 ? null : (s as Set<string>);
}

export function getGamesByCategory(
  slug: CategorySlug,
  excludeSlugs?: Iterable<string>,
): readonly Game[] {
  const slugs = gamesByCategoryMap[slug] ?? [];
  const excl = toExcludeSet(excludeSlugs);
  const result: Game[] = [];
  for (const s of slugs) {
    if (excl && excl.has(s)) continue;
    const g = slugToGame.get(s);
    if (g) result.push(g);
  }
  return result;
}

export function getTrendingGames(excludeSlugs?: Iterable<string>): readonly Game[] {
  const excl = toExcludeSet(excludeSlugs);
  const list: Game[] = [];
  for (const g of allGames) {
    if (excl && excl.has(g.slug)) continue;
    list.push(g);
    if (list.length >= 12) break;
  }
  return list;
}

export function getTopPicks(excludeSlugs?: Iterable<string>): readonly Game[] {
  const excl = toExcludeSet(excludeSlugs);
  const list: Game[] = [];
  for (const g of allGames) {
    if (excl && excl.has(g.slug)) continue;
    list.push(g);
    if (list.length >= 24) break;
  }
  return list;
}

export function getFeaturedGame(): Game & { description: string; thumbnailWide: string } {
  const moto = slugToGame.get("moto-x3m");
  const racingSlugs = gamesByCategoryMap.racing;
  const firstRacing = racingSlugs.length > 0 ? slugToGame.get(racingSlugs[0]) : undefined;
  const base = moto ?? firstRacing ?? allGames[0];
  return {
    ...base,
    description: base.description ?? "ألعاب جديدة تنتظرك — العب الآن بدون تحميل",
    thumbnailWide: base.thumbnail,
  };
}

export function getGameBySlug(slug: string): Game | undefined {
  return slugToGame.get(slug);
}

